/**
 * One-off: recompute reading time for every post, and regenerate excerpts that were
 * auto-generated by the old htmlToText (which glued words across block boundaries).
 * Hand-written excerpts are left alone: only an excerpt that exactly matches what the
 * old logic would have produced from the post's content is replaced.
 *
 *   pnpm --filter api content:recompute          # apply
 *   pnpm --filter api content:recompute --dry    # report only
 */
import { prisma } from "../lib/prisma.js";
import { makeExcerpt, readingTimeMinutes, stripTags } from "../lib/content.js";

const dry = process.argv.includes("--dry");

/** The pre-fix behaviour: no space between "</p><p>" etc. */
const oldHtmlToText = stripTags;

function oldMakeExcerpt(html: string, maxLength: number): string {
  const text = oldHtmlToText(html);
  if (text.length <= maxLength) return text;
  const cut = text.slice(0, maxLength);
  return `${cut.slice(0, cut.lastIndexOf(" ")).replace(/[,.;:!?-]+$/, "")}…`;
}

// Auto excerpt lengths used by the API (200) and the WordPress importer (220).
const AUTO_LENGTHS = [200, 220];

async function main() {
  const posts = await prisma.post.findMany({
    select: { id: true, slug: true, content: true, excerpt: true, readingTimeMinutes: true },
  });

  let readingChanged = 0;
  let excerptChanged = 0;
  for (const p of posts) {
    const readingTime = readingTimeMinutes(p.content);
    const autoLength = AUTO_LENGTHS.find((n) => p.excerpt !== null && p.excerpt === oldMakeExcerpt(p.content, n));
    const excerpt = autoLength ? makeExcerpt(p.content, autoLength) : p.excerpt;

    const changes: string[] = [];
    if (readingTime !== p.readingTimeMinutes) changes.push(`reading ${p.readingTimeMinutes} → ${readingTime} min`);
    if (excerpt !== p.excerpt) changes.push("excerpt regenerated");
    if (changes.length === 0) continue;

    console.log(`${p.slug}: ${changes.join(", ")}`);
    if (readingTime !== p.readingTimeMinutes) readingChanged++;
    if (excerpt !== p.excerpt) excerptChanged++;
    if (!dry) {
      await prisma.post.update({ where: { id: p.id }, data: { readingTimeMinutes: readingTime, excerpt } });
    }
  }

  console.log(
    `${dry ? "[dry run] " : ""}${posts.length} posts checked: ${readingChanged} reading times, ${excerptChanged} excerpts updated`,
  );
}

main()
  .catch((err) => {
    console.error(err);
    process.exitCode = 1;
  })
  .finally(() => prisma.$disconnect());
